/* Bounded GL3.3 mapping via guest-visible staging. SPDX-License-Identifier: MIT.
 * CPU shadows never substitute for GPU-generated bytes: map snapshots native storage in order.
 * GL_MAP_UNSYNCHRONIZED_BIT is a permission to omit waiting, not a requirement to do so. */
static int buffer_read(Buffer *b, uint32_t off, uint32_t n, uint8_t *data) {
    if (!n) return 1;
    if (!b->generated) { copy(data, b->data + off, n); return 1; }
    uint32_t req = ++request_id, words[] = {b->gpu, off, n, req};
    if (!send(0x63, words, 4)) return 0;
    int status; while ((status = bgt_request_status(req)) == 0) w32_wait_frame();
    int got = status > 0 ? bgt_request_read(req, data, n) : -1; bgt_request_close(req);
    if (got != (int)n) { fail(BAD_OP); return 0; } return 1;
}
static void unmap_storage(Buffer *b) {
    if (b->map) w32_heap_free(b->map);
    b->map = b->map_offset = b->map_size = b->map_flags = 0;
}
static uint32_t map_buffer(Buffer *b, uint64_t off, uint64_t n, uint32_t flags, uint32_t access) {
    if (b->map) { fail(BAD_OP); return 0; }
    if (off > b->size || n > b->size - off) { fail(BAD_VALUE); return 0; }
    if (!n) { fail(BAD_OP); return 0; }
    if (tf_active) for (uint32_t i = 0; i < 4; i++) if (tf_bound[i] == (uint32_t)(b - buffers)) { fail(BAD_OP); return 0; }
    uint32_t p = w32_heap_alloc((uint32_t)n, 0); if (!p) { fail(OOM); return 0; }
    /* A write-only invalidated mapping need not preserve the previous range. */
    if (!(flags & 0x0c)) {
        uint8_t *data = glp_alloc((uint32_t)n);
        if (!data) { w32_heap_free(p); fail(OOM); return 0; }
        int ok = buffer_read(b, (uint32_t)off, (uint32_t)n, data);
        if (ok) for (uint32_t i = 0; i < n; i++) x86_wr8(p + i, data[i]);
        glp_free(data, (uint32_t)n); if (!ok) { w32_heap_free(p); return 0; }
    }
    b->map = p; b->map_offset = (uint32_t)off; b->map_size = (uint32_t)n;
    b->map_flags = flags; b->map_access = access; return p;
}
static uint32_t api_MapBuffer(void) {
    Buffer *b = bound_buffer(ARG(0)); if (!b) return 0;
    uint32_t access = ARG(1), flags = access == 0x88b8 ? 1 : access == 0x88b9 ? 2 : access == 0x88ba ? 3 : 0;
    if (!flags) { fail(BAD_ENUM); return 0; }
    uint32_t p = map_buffer(b, 0, b->size, flags, access);
    if (p) default_element_compat(ARG(0), "core VAO 0 element-buffer map");
    return p;
}
static uint32_t api_MapBufferRange(void) {
    Buffer *b = bound_buffer(ARG(0)); if (!b) return 0;
    uint32_t flags = ARG(3);
    if (flags & ~0x3fu) { fail(BAD_VALUE); return 0; }
    if (!(flags & 3) || ((flags & 1) && (flags & 0x2c)) || ((flags & 0x10) && !(flags & 2))) { fail(BAD_OP); return 0; }
    uint32_t p = map_buffer(b, ARG64(1), ARG64(2), flags, flags & 1 ? (flags & 2 ? 0x88ba : 0x88b8) : 0x88b9);
    if (p) default_element_compat(ARG(0), "core VAO 0 element-buffer map");
    return p;
}
static int mapped_upload(Buffer *b, uint32_t off, uint32_t n) {
    if (!n) return 1;
    uint32_t at = b->map_offset + off;
    /* Native BUFFER_UPDATE cannot preserve generated neighbours for odd byte writes. Snapshot
     * the complete native buffer then upload an authoritative replacement (no stale shadow). */
    int whole = b->generated && ((at & 3) || (n & 3)) && (at || n != b->size);
    uint32_t size = whole ? b->size : n, dest = whole ? 0 : at;
    uint8_t *data = glp_alloc(size); if (!data) { fail(OOM); return 0; }
    if (whole && !buffer_read(b, 0, b->size, data)) { glp_free(data, size); return 0; }
    for (uint32_t i = 0; i < n; i++) data[(whole ? at : 0) + i] = x86_rd8(b->map + off + i);
    uint32_t words[] = {b->gpu, dest, PTR(data), size}; int ok = send(0x41, words, 4);
    if (ok) { copy(b->data + dest, data, size); if (!dest && size == b->size) b->generated = 0; }
    glp_free(data, size); return ok;
}
static uint32_t api_FlushMappedBufferRange(void) {
    Buffer *b = bound_buffer(ARG(0)); if (!b) return 0;
    if (!b->map || !(b->map_flags & 0x10)) { fail(BAD_OP); return 0; }
    uint64_t off = ARG64(1), n = ARG64(2);
    if (off > b->map_size || n > b->map_size - off) { fail(BAD_VALUE); return 0; }
    if (mapped_upload(b, (uint32_t)off, (uint32_t)n))
        default_element_compat(ARG(0), "core VAO 0 element-buffer mapped upload");
    return 0;
}
static uint32_t api_UnmapBuffer(void) {
    Buffer *b = bound_buffer(ARG(0)); if (!b) return 0;
    if (!b->map) { fail(BAD_OP); return 0; }
    int ok = !(b->map_flags & 2) || (b->map_flags & 0x10) || mapped_upload(b, 0, b->map_size);
    if (ok && (b->map_flags & 2) && !(b->map_flags & 0x10))
        default_element_compat(ARG(0), "core VAO 0 element-buffer mapped upload");
    unmap_storage(b); return !!ok;
}
static uint32_t api_GetBufferPointerv(void) {
    Buffer *b = bound_buffer(ARG(0)); if (!b) return 0;
    if (ARG(1) != 0x88bd) { fail(BAD_ENUM); return 0; }
    w32_wrptr(ARG(2), b->map); return 0;
}
